export class DomEmitter<K extends keyof HTMLElementEventMap> implements IDisposable {

	private emitter: Emitter<HTMLElementEventMap[K]>;

	get event(): BaseEvent<HTMLElementEventMap[K]> {
		return this.emitter.event;
